from .session_handler import SessionHandler
from .abstracts import NodeOam


class nodeoam_client(object):
    """Robot Framework keywords interface"""

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.session_handler = SessionHandler()

    def create_session(self, base_url, connection, socat_port='18018',
                       fsm_ip='192.168.2.60', fsm_port='8090'):
        """
        Starts socat on OAM node, which by default is listening on port 18018
        and it forwards all requests from that port to fsm on port 8090.
        Requires alias of ssh connection to OAM.

        :param base_url: Url example: http://10.42.44.200. Url can be with or
        without the http:// header
        :param connection: Alias of ssh connection to OAM, which can be created
        by connect_to method from taf.transport.ssh library.
        :param socat_port: Any free port, where socat can listen for requests,
        default value is 18018.
        :param fsm_ip: IP address assigned to fsm interface, from which
        a connection with OAM can be established.
        :param fsm_port: Port on fsm onto which nodeoam listening for requests.
        """
        self.session_handler.create_session(base_url=base_url,
                                            connection=connection,
                                            socat_port=socat_port,
                                            fsm_ip=fsm_ip,
                                            fsm_port=fsm_port)

    def create_direct_session(self, fsm_ip='192.168.255.1', fsm_port='8090'):
        """
        Requires direct connection to fsm (for example from test PC
        via LMP port).
        :param fsm_ip: fsm IP address
        :param fsm_port: Port on fsm onto which nodeoam listening for requests.
        """
        self.session_handler.create_direct_session(fsm_ip, fsm_port)

    def get_fsm(self, attribute=None, fsm_id='1'):
        """
        :param string attribute: status that you want to check
        :param fsm_id: id of system module
        :return: value(s) of given attribute from fsm, if attribute is
            None- returns whole json from fsm as dictionary.
        """
        return NodeOam(self.session_handler).get_fsm(attribute, fsm_id)

    def get_fbb(self, attribute=None, fbb_id='1'):
        """
        :param string attribute: status that you want to check
        :param fbb_id: id of broadband
        :return: value(s) of given attribute from fbb, if attribute is
            None- returns whole json from fbb as dictionary.
        """
        return NodeOam(self.session_handler).get_fbb(attribute, fbb_id)

    def get_system_module_fct(self, attribute=None, fsm_id=None):
        """
        :param string attribute: status that you want to check
        :param fsm_id: id of system module
        :return: value(s) of given attribute from fct, if attribute is
            None- returns whole json from fct as dictionary.
        """
        return NodeOam(self.session_handler).get_fct(attribute, fsm_id)

    def get_broadband_fsp(self, attribute=None, fbb_id=None):
        """
        :param string attribute: status that you want to check
        :param fbb_id: id of broadband
        :return: value(s) of given attribute from fsp, if attribute is
            None- returns whole json from fsp as dictionary.
        """
        return NodeOam(self.session_handler).get_fsp(attribute, fbb_id)

    def activate_fsm_temperature_test_mode(self, fsm_id='1'):
        """
        Activates temperature test mode on specified fsm.

        :param fsm_id: id of system module
        """
        return NodeOam(self.session_handler).set_fsm_temperature_test_mode(
            enter_testmode=True, fsm_id=fsm_id)

    def deactivate_fsm_temperature_test_mode(self, fsm_id='1'):
        """
        Deactivates temperature test mode on specified fsm.

        :param fsm_id: id of system module
        """
        return NodeOam(self.session_handler).set_fsm_temperature_test_mode(
            enter_testmode=False, fsm_id=fsm_id)

    def activate_fsm_fan_test_mode(self, fsm_id='1'):
        """
        Activates fan test mode on specified fsm.

        :param fsm_id: id of system module
        """
        return NodeOam(self.session_handler).set_fsm_fan_test_mode(
            enter_testmode=True, fsm_id=fsm_id)

    def deactivate_fsm_fan_test_mode(self, fsm_id='1'):
        """
        Deactivates fan test mode on specified fsm.

        :param fsm_id: id of system module
        """
        return NodeOam(self.session_handler).set_fsm_fan_test_mode(
            enter_testmode=False, fsm_id=fsm_id)

    def set_temperatures_on_sensor_group(self, sensor_group_type,
                                         sensor_id_to_temperature):
        """
        This keyword use PUT on /mz/p/v1/clic/setTemperatures endpoint and
        sets the temperatures on the defined sensors.

        :param string sensor_group_type: Name of sensor group, for example:
        'ETempSensorType_Fct'.
        :param dict sensor_id_to_temperature: Dictionary with pairs of sensor
        name and it's temperature, for example:
        {"ETempSensorFct": 48, "ETempSensorFctMurkku": 48}
        :return:
        """
        return NodeOam(self.session_handler).set_temperatures(
            sensor_group_type, sensor_id_to_temperature)

    def set_fsm_fan_speeds(self, fan1_speed=None, fan1_status=None,
                           fan2_speed=None, fan2_status=None):
        """
        This keyword  use PUT on /mz/p/v1/clic/setFanSpeeds endpoint and sets
        the fsm fans speed and status.

        :param fan1_speed, fan2_speed: Fan speed in RPM, can be string or int.
        By default each fan speed is set to 4300 RPM.
        :param fan1_status, fan2_status: Status, that you want to set.
        By default each fan status is set to EStatus_NoError.
        :return:
        """
        return NodeOam(self.session_handler).set_fan_speeds(
            fan1_speed, fan1_status, fan2_speed, fan2_status)

    def get_fsp_sensors_names(self, fbb_id='1'):
        """
        :param fbb_id: Id of broadband. Can be string or int.
        :return: List with names of all fsp sensors.
        """
        return NodeOam(self.session_handler).get_fsp_sensors_names(fbb_id)

    def set_sensors_fault_state(self, sensor_group_type, sensors_parameters):
        """
        This keyword use PUT on /mz/p/v1/clic/setTemperatures endpoint and
        sets the temperature, state and fault id on the defined sensors.

        :param string sensor_group_type: Name of sensor group, for example:
        'ETempSensorType_Fct'.
        :param sensors_parameters: Dictionary with pairs of sensor name and dict
        with it's: temperature, state and fault_id, for example:
        {"ETempSensorFct": {"temperature": 48,
                            "temp_sensor_state": 1,
                            "i2c_fault_id": 0},
        "ETempSensorFctEnv": {"temperature": 50,
                              "temp_sensor_state": 1,
                              "i2c_fault_id": 0}
        }
        :return:
        """
        return NodeOam(self.session_handler).set_sensors_fault_state(
            sensor_group_type, sensors_parameters)

    def install_certificate(self, p12_path, password=''):
        """
        Send a pkcs12 file to nodeoam for certificate installation.

        :param string p12_path: path to pkcs #12 file that contains keystore
        :param string password: (optional) password for the pkcs file
        """
        with open(p12_path, 'rb') as f:
            pkcs_data = f.read()

        NodeOam(self.session_handler).install_certificate(pkcs_data, password)
